package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

// Data Division derived types
type SalesRec struct { // 01 SALES-REC, 12 bytes
	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

type TierTable struct { // 01 TIER-TABLE (occurs 4)
	TierEntry struct {
		TierLimit decimal.Decimal // PIC 9(6)V99
		TierRate  decimal.Decimal // PIC 9V99
	}
}

// Working-storage
var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.Zero
var WsTotal decimal.Decimal = decimal.Zero
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

// internal helpers
var tierLimits [5]decimal.Decimal // 1-based
var tierRates [5]decimal.Decimal
var curSalesRec SalesRec
var salesFileRecords []string
var salesFileIdx int

func storeDecimal(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	if intDigits <= 0 {
		return v
	}
	sign := v.Sign()
	abs := v.Abs()
	intPart := abs.Truncate(0)
	frac := abs.Sub(intPart)
	pow10 := int64(1)
	for i := 0; i < intDigits; i++ {
		pow10 *= 10
	}
	divisor := decimal.NewFromInt(pow10)
	q := intPart.Div(divisor).Truncate(0)
	intMod := intPart.Sub(q.Mul(divisor))
	resAbs := intMod.Add(frac)
	if sign < 0 {
		resAbs = resAbs.Neg()
	}
	return resAbs
}

func storeInt(v int64, digits int) int64 {
	pow10 := int64(1)
	for i := 0; i < digits; i++ {
		pow10 *= 10
	}
	if pow10 == 0 {
		return v
	}
	r := v % pow10
	if r < 0 {
		r = -r
	}
	return r
}

func formatEdited(v decimal.Decimal, picture string) string {
	dotIdx := strings.Index(picture, ".")
	var intPic string
	var fracDigits int
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic := picture[dotIdx+1:]
		fracDigits = len(fracPic)
	} else {
		intPic = picture
		fracDigits = 0
	}
	intEditDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intEditDigits++
		}
	}
	abs := v.Abs()
	intPartDec := abs.Truncate(0)
	intPartInt := intPartDec.IntPart()
	pow10 := int64(1)
	for i := 0; i < intEditDigits; i++ {
		pow10 *= 10
	}
	var intMod int64
	if pow10 != 0 && intEditDigits > 0 {
		intMod = intPartInt % pow10
		if intMod < 0 {
			intMod = -intMod
		}
	}
	var fracInt int64
	if fracDigits > 0 {
		frac := abs.Sub(intPartDec)
		shifted := frac.Shift(int32(fracDigits))
		fracInt = shifted.Truncate(0).IntPart()
		if fracInt < 0 {
			fracInt = -fracInt
		}
	}
	intStr := ""
	if intEditDigits > 0 {
		intStr = fmt.Sprintf("%0*d", intEditDigits, intMod)
	}
	outInt := make([]byte, len(intPic))
	digitIdx := 0
	suppressed := true
	for i, ch := range intPic {
		if ch == ',' {
			if suppressed {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		} else if ch == 'Z' {
			var d byte = '0'
			if digitIdx < len(intStr) {
				d = intStr[digitIdx]
			}
			digitIdx++
			if suppressed {
				if d == '0' {
					outInt[i] = ' '
				} else {
					outInt[i] = d
					suppressed = false
				}
			} else {
				outInt[i] = d
			}
		} else if ch == '9' {
			var d byte = '0'
			if digitIdx < len(intStr) {
				d = intStr[digitIdx]
			}
			digitIdx++
			outInt[i] = d
			suppressed = false
		} else {
			outInt[i] = byte(ch)
		}
	}
	result := string(outInt)
	if fracDigits > 0 {
		fracStr := fmt.Sprintf("%0*d", fracDigits, fracInt)
		result = result + "." + fracStr
	}
	if v.IsNegative() && len(result) > 0 {
		// simple sign handling (not needed for test data)
		// replace first space with '-'
		b := []byte(result)
		for i := range b {
			if b[i] == ' ' {
				b[i] = '-'
				break
			}
			if b[i] != ' ' && b[i] != ',' {
				// no leading space, prepend minus (should not happen for our pictures)
				break
			}
		}
		result = string(b)
		if result[0] != '-' {
			result = "-" + result[1:]
		}
	}
	return result
}

func formatUneditedInt(v int64, width int) string {
	pow10 := int64(1)
	for i := 0; i < width; i++ {
		pow10 *= 10
	}
	mod := v % pow10
	if mod < 0 {
		mod = -mod
	}
	return fmt.Sprintf("%0*d", width, mod)
}

func openSalesFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		salesFileRecords = nil
		salesFileIdx = 0
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	var recs []string
	for scanner.Scan() {
		line := scanner.Text()
		if len(line) < 12 {
			line = line + strings.Repeat(" ", 12-len(line))
		} else if len(line) > 12 {
			line = line[:12]
		}
		recs = append(recs, line)
	}
	salesFileRecords = recs
	salesFileIdx = 0
}

func INITPARA() {
	tierLimits[1] = decimal.New(100000, -2)
	tierRates[1] = decimal.New(250, -2)
	tierLimits[2] = decimal.New(500000, -2)
	tierRates[2] = decimal.New(400, -2)
	tierLimits[3] = decimal.New(2000000, -2)
	tierRates[3] = decimal.New(550, -2)
	tierLimits[4] = decimal.New(99999999, -2)
	tierRates[4] = decimal.New(725, -2)
}

func READPARA() {
	if salesFileIdx >= len(salesFileRecords) {
		WsEofFlag = "Y"
		return
	}
	rec := salesFileRecords[salesFileIdx]
	salesFileIdx++
	srId := rec[0:4]
	srSalesStr := rec[4:12]
	trimmed := strings.TrimSpace(srSalesStr)
	var intVal int64
	if trimmed == "" {
		intVal = 0
	} else {
		v, err := strconv.ParseInt(trimmed, 10, 64)
		if err != nil {
			// filter digits
			digitsOnly := ""
			for _, ch := range trimmed {
				if ch >= '0' && ch <= '9' {
					digitsOnly += string(ch)
				} else if ch == '-' {
					digitsOnly += string(ch)
				}
			}
			if digitsOnly == "" || digitsOnly == "-" {
				intVal = 0
			} else {
				v2, err2 := strconv.ParseInt(digitsOnly, 10, 64)
				if err2 != nil {
					intVal = 0
				} else {
					intVal = v2
				}
			}
		} else {
			intVal = v
		}
	}
	curSalesRec.SrId = srId
	curSalesRec.SrSales = decimal.New(intVal, -2)
	WsEofFlag = "N"
}

func PROCESSPARA() {
	WsTier = 0
	WsIdx = 1
	for {
		if WsIdx > 4 || WsTier > 0 {
			break
		}
		if curSalesRec.SrSales.Cmp(tierLimits[WsIdx]) <= 0 {
			WsTier = storeInt(WsIdx, 1)
		}
		WsIdx = storeInt(WsIdx+1, 1)
	}
	tierRate := tierRates[WsTier]
	prod := curSalesRec.SrSales.Mul(tierRate)
	divided := prod.Shift(-2)
	rounded := divided.Round(2)
	WsComm = storeDecimal(rounded, 6, 2)
	WsTotal = WsTotal.Add(WsComm)
	WsTotal = storeDecimal(WsTotal, 9, 2)
	WsCount = storeInt(WsCount+1, 3)
	WsSalesEd = formatEdited(curSalesRec.SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatEdited(tierRate, "9.99")
	WsCommEd = formatEdited(WsComm, "ZZZ,ZZ9.99")
	tierStr := formatUneditedInt(WsTier, 1)
	line := curSalesRec.SrId + " T" + tierStr + " " + WsSalesEd + " " + WsRateEd + "% " + WsCommEd
	fmt.Println(line)
	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsCount, 3)
	line := "REPS: " + countStr + " TOTAL: " + WsTotalEd
	fmt.Println(line)
}

func MAINPARA() {
	INITPARA()
	openSalesFile()
	READPARA()
	for WsEofFlag != "Y" {
		PROCESSPARA()
	}
	SUMMARYPARA()
}

func main() {
	MAINPARA()
}
